import math
import re
from datetime import datetime

CURRENCY_RE = re.compile(r"[A-Z]{3}")


def _validate(record, loaded_ids):
    """Renvoie (raison_du_rejet, None) ou (None, enregistrement_normalisé)."""
    if not isinstance(record, dict):
        return "not_an_object", None

    # event_id : obligatoire, chaîne non vide après strip
    value = record.get("event_id")
    if value is None:
        return "missing_event_id", None
    if not isinstance(value, str) or not value.strip():
        return "invalid_event_id", None
    event_id = value.strip()

    # user_id : obligatoire, entier (pas bool) ou chaîne de chiffres, > 0
    value = record.get("user_id")
    if value is None:
        return "missing_user_id", None
    if isinstance(value, bool):                       # True est un int en Python
        return "invalid_user_id", None
    if isinstance(value, int):
        user_id = value
    elif isinstance(value, str) and value.strip().isdigit():
        user_id = int(value.strip())
    else:
        return "invalid_user_id", None
    if user_id <= 0:
        return "invalid_user_id", None

    # amount : obligatoire, nombre (pas bool) ou chaîne numérique, fini et >= 0
    value = record.get("amount")
    if value is None:
        return "missing_amount", None
    if isinstance(value, bool):
        return "invalid_amount", None
    if isinstance(value, (int, float)):
        amount = float(value)
    elif isinstance(value, str):
        try:
            amount = float(value.strip())
        except ValueError:
            return "invalid_amount", None
    else:
        return "invalid_amount", None
    if not math.isfinite(amount) or amount < 0:      # float("nan") et float("inf") passent sinon
        return "invalid_amount", None

    # currency : facultative (absente ou null => EUR), sinon 3 lettres après strip/upper
    value = record.get("currency")
    if value is None:
        currency = "EUR"
    elif isinstance(value, str) and CURRENCY_RE.fullmatch(value.strip().upper()):
        currency = value.strip().upper()
    else:
        return "invalid_currency", None

    # ts : obligatoire, chaîne au format exact YYYY-MM-DDTHH:MM:SSZ, date réelle
    value = record.get("ts")
    if value is None:
        return "missing_ts", None
    if not isinstance(value, str):
        return "invalid_ts", None
    try:
        datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError:
        return "invalid_ts", None

    # doublon : seulement parmi les enregistrements déjà CHARGÉS
    if event_id in loaded_ids:
        return "duplicate_event_id", None

    return None, {"event_id": event_id, "user_id": user_id, "amount": round(amount, 2),
                  "currency": currency, "ts": value}


def ingest_events(fetch_batch) -> dict:
    try:
        response = fetch_batch()
    except Exception as exc:
        return {"status": "error", "error": type(exc).__name__, "batch_id": None,
                "read": 0, "loaded": 0, "rejected": 0, "rejections": {}, "records": []}

    records = response.get("records") or []
    loaded = []
    loaded_ids = set()
    rejections = {}
    for record in records:
        reason, clean = _validate(record, loaded_ids)
        if reason is None:
            loaded.append(clean)
            loaded_ids.add(clean["event_id"])
        else:
            rejections[reason] = rejections.get(reason, 0) + 1

    return {
        "status": "ok",
        "error": None,
        "batch_id": response.get("batch_id"),
        "read": len(records),
        "loaded": len(loaded),
        "rejected": len(records) - len(loaded),
        "rejections": rejections,
        "records": loaded,
    }

